# ---------------------


def parse_numbers(source: Union[str, List[int]]) -> List[int]:
    if isinstance(source, list):
        return source
    
    data = source
    # Check if it's a file path
    if len(source) < 1024 and os.path.exists(source) and os.path.isfile(source):
        try:
            with open(source, "r", encoding="utf-8") as f:
                data = f.read()
        except Exception:
            pass # Treat as raw string if read fails
            
    # Extract all numbers using regex
    # Matches standard integers (123), negatives (-123)
    tokens = re.findall(r"-?\d+", data)
    return [int(x) for x in tokens]


def center_mod_q(x: int, q: int) -> int:
    x %= q
    if x > q // 2:
        x -= q
    return x


def center_mod_beta(x: int, beta: int) -> int:
    m = 1 << beta
    x %= m
    if x >= m // 2:
        x -= m
    return x


def compute_qinv_centered(vals_q_centered: List[int], q: int, beta: int) -> List[int]:
    m = 1 << beta
    # Calculate modular inverse of q modulo 2^beta
    try:
        qinv = pow(q, -1, m)
    except ValueError:
        print(f"Error: q={q} is not invertible modulo 2^{beta}")
        return []

    out: List[int] = []
    for v in vals_q_centered:
        # v is in [-q/2, q/2]. We compute (v * qinv) mod 2^beta
        y = (v * qinv) % m
        out.append(center_mod_beta(y, beta))
    return out


def print_aligned_array(name: str, data: List[int], group: int = 16) -> None:
    # Find the max width needed for any number in the list
    # Add 1 for potential comma
    max_width = max(len(str(x)) for x in data)
    
    print(f"int32_t {name}[{len(data)}] = {{")
    for i, v in enumerate(data):
        if i % group == 0:
            print("    ", end="")
        
        # Format with fixed width, right aligned
        v_str = str(v)
        end_char = "," if i < len(data) - 1 else ""
        # Adjust padding to account for the comma
        print(f"{v_str + end_char:>{max_width + 1}}", end="")
        
        # Add space after comma unless it's the end of the line
        if (i + 1) % group != 0:
            print(" ", end="")
        else:
            print("")
            
    if len(data) % group != 0:
        print("")
    print("};\n")


def main():
    print(f"// Generating tables with Q={Q}, Beta={BETA}, Skip_Mont={SKIP_MONT}")
    
    tree = parse_numbers(TREE_DATA)
    tree_inv = parse_numbers(TREE_INV_DATA)
    
    print(f"// Loaded {len(tree)} elements for tree")
    print(f"// Loaded {len(tree_inv)} elements for tree_inv\n")
    
    if not tree or not tree_inv:
        print("// Warning: Empty input data found.")

    mont = pow(2, BETA, Q)

    # 1. Tree centered (±q)
    centered_tree = [center_mod_q(x, Q) for x in tree]
    
    # 2. Tree_inv centered (±q)
    centered_tree_inv = [center_mod_q(x, Q) for x in tree_inv]

    if SKIP_MONT:
        # If already in mont domain, just use them for qinv calc
        tree_for_qinv = centered_tree
        tree_inv_for_qinv = centered_tree_inv
    else:
        # Multiply by MONT then center
        tree_for_qinv = [center_mod_q((x * mont) % Q, Q) for x in tree]
        tree_inv_for_qinv = [center_mod_q((x * mont) % Q, Q) for x in tree_inv]

    # 3. Tree_qinv centered (±β)
    centered_tree_qinv = compute_qinv_centered(tree_for_qinv, Q, BETA)
    
    # 4. Tree_inv_qinv centered (±β)
    centered_tree_inv_qinv = compute_qinv_centered(tree_inv_for_qinv, Q, BETA)

    print_aligned_array("tree_centered", centered_tree)
    print_aligned_array("tree_inv_centered", centered_tree_inv)
    print_aligned_array("tree_qinv_centered", centered_tree_qinv)
    print_aligned_array("tree_inv_qinv_centered", centered_tree_inv_qinv)


if __name__ == "__main__":
    main()
